public partial class ShowService
{
    private async partial Task<Error?> CheckCapacityAsync(Show aggregate, CancellationToken cancellationToken)
    {
        var venue = await VenueRepository.FindAsync(aggregate.VenueId, cancellationToken);
        if (venue is null)
        {
            return null; // reported by the reference validation
        }
        var total = aggregate.TicketTiers.Sum(t => (long)t.Quota);
        if (total > venue.Capacity)
        {
            return Error.Invalid(new Dictionary<string, string[]>
            {
                ["TicketTiers"] = [$"The quotas of the tiers ({total}) exceed the capacity of the venue ({venue.Capacity})"],
            });
        }
        return null;
    }
}
