namespace Acme.Ticketing.Tests;

[TestClass]
public class TicketingTests : ApiTestBase
{
    private async Task<JsonElement> CreateVenueAsync(string name = "Arena", int capacity = 100) =>
        await PostAsync<JsonElement>("/venues", new
        {
            name,
            capacity,
            address = new { street = "1 Main St", city = "Paris", postalCode = "75001" },
        });

