    [TestMethod]
    public async Task VenueRoundTrip()
    {
        var venue = await CreateVenueAsync();
        var id = venue.GetProperty("id").GetGuid();
        Assert.AreEqual("Paris", venue.GetProperty("address").GetProperty("city").GetString());

        var dup = await Client.PostAsJsonAsync("/venues", new { name = "Arena", capacity = 1, address = new { street = "s", city = "c", postalCode = "p" } });
        Assert.AreEqual(HttpStatusCode.Conflict, dup.StatusCode);

        var bad = await Client.PostAsJsonAsync("/venues", new { name = "", capacity = 1, address = new { street = "s", city = "c", postalCode = "p" } });
        await AssertInvalidAsync(bad, "Name");

        var put = await Client.PutAsJsonAsync($"/venues/{id}", new { name = "Arena2", capacity = 50, address = new { street = "s", city = "c", postalCode = "p" } });
        Assert.AreEqual(HttpStatusCode.OK, put.StatusCode);

        var page = await Client.GetFromJsonAsync<JsonElement>("/venues?orderBy=Name&descending=true");
        Assert.AreEqual(1, page.GetProperty("totalCount").GetInt32());
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?page=0")).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?pageSize=201")).StatusCode);
        Assert.AreEqual(HttpStatusCode.BadRequest, (await Client.GetAsync("/venues?orderBy=Nope")).StatusCode);

        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/venues/{id}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.NotFound, (await Client.GetAsync($"/venues/{id}")).StatusCode);
    }

    [TestMethod]
    public async Task ShowTiersSyncAndCapacity()
    {
        var venueId = (await CreateVenueAsync(capacity: 20)).GetProperty("id").GetGuid();
        var show = await CreateShowAsync(venueId, status: 0);
        var id = show.GetProperty("id").GetGuid();
        var tier = show.GetProperty("ticketTiers")[0];
        Assert.AreEqual(0, tier.GetProperty("sold").GetInt32());

        var got = await Client.GetFromJsonAsync<JsonElement>($"/shows/{id}");
        Assert.IsFalse(got.GetProperty("isSoldOut").GetBoolean());
        Assert.AreEqual(0, got.GetProperty("status").GetInt32());

        var venue = await Client.GetFromJsonAsync<JsonElement>($"/venues/{venueId}");
        Assert.AreEqual(1, venue.GetProperty("shows").GetArrayLength());
        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/venues/{venueId}")).StatusCode);

        // update one tier, add one, over capacity
        var over = await Client.PutAsJsonAsync($"/shows/{id}", new
        {
            title = "T", startsAt = DateTime.UtcNow.AddDays(1), status = 0, venueId,
