        await AssertInvalidAsync(over, "TicketTiers");

        var ok = await Client.PutAsJsonAsync($"/shows/{id}", new
        {
            title = "T", startsAt = DateTime.UtcNow.AddDays(1), status = 0, venueId,
            ticketTiers = new object[] { new { id = tier.GetProperty("id").GetGuid(), name = "Std2", price = 1, quota = 15 }, new { name = "VIP", price = 2, quota = 5 } },
        });
        Assert.AreEqual(HttpStatusCode.OK, ok.StatusCode, await ok.Content.ReadAsStringAsync());
        var updated = await ok.Content.ReadFromJsonAsync<JsonElement>();
        Assert.AreEqual(2, updated.GetProperty("ticketTiers").GetArrayLength());

        var removed = await Client.PutAsJsonAsync($"/shows/{id}", new
        {
            title = "T", startsAt = DateTime.UtcNow.AddDays(1), status = 0, venueId, ticketTiers = Array.Empty<object>(),
