    [TestMethod]
    public async Task BookingFlow()
    {
        var venueId = (await CreateVenueAsync()).GetProperty("id").GetGuid();
        var show = await CreateShowAsync(venueId, quota: 4);
        var showId = show.GetProperty("id").GetGuid();

        await AssertInvalidAsync(await BookAsync(showId, quantity: 0), "Quantity");
        await AssertInvalidAsync(await BookAsync(showId, quantity: 11), "Quantity");
        await AssertInvalidAsync(await BookAsync(showId, email: "nope"), "CustomerEmail");
        Assert.AreEqual(HttpStatusCode.NotFound, (await BookAsync(Guid.NewGuid())).StatusCode);
        await AssertInvalidAsync(await BookAsync(showId, tier: "Nope"), "Tier");
        Assert.AreEqual(HttpStatusCode.Conflict, (await BookAsync(showId, quantity: 5)).StatusCode);

        var response = await BookAsync(showId, quantity: 2);
        Assert.AreEqual(HttpStatusCode.OK, response.StatusCode, await response.Content.ReadAsStringAsync());
        var booking = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.AreEqual(25m, booking.GetProperty("totalPrice").GetDecimal());

        Assert.AreEqual(HttpStatusCode.Conflict, (await BookAsync(showId, quantity: 3)).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await BookAsync(showId, quantity: 2)).StatusCode);

        var got = await Client.GetFromJsonAsync<JsonElement>($"/shows/{showId}");
        Assert.IsTrue(got.GetProperty("isSoldOut").GetBoolean());
        Assert.AreEqual(4, got.GetProperty("ticketTiers")[0].GetProperty("sold").GetInt32());

        // a PUT cannot change sold
        var tierId = got.GetProperty("ticketTiers")[0].GetProperty("id").GetGuid();
        var put = await Client.PutAsJsonAsync($"/shows/{showId}", new
        {
            title = "T", startsAt = DateTime.UtcNow.AddDays(1), status = 1, venueId,
            ticketTiers = new[] { new { id = tierId, name = "Std", price = 1, quota = 4, sold = 0 } },
        });
        Assert.AreEqual(4, (await put.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("ticketTiers")[0].GetProperty("sold").GetInt32());

        var bookings = await Client.GetFromJsonAsync<JsonElement>("/bookings");
        Assert.AreEqual(2, bookings.GetProperty("totalCount").GetInt32());
        Assert.AreEqual(HttpStatusCode.Conflict, (await Client.DeleteAsync($"/shows/{showId}")).StatusCode);
    }

    [TestMethod]
    public async Task BookingRefusesDraftCancelledAndPastShows()
    {
        var venueId = (await CreateVenueAsync()).GetProperty("id").GetGuid();
        foreach (var status in new[] { 0, 2 })
        {
            var s = await CreateShowAsync(venueId, status: status);
            Assert.AreEqual(HttpStatusCode.Conflict, (await BookAsync(s.GetProperty("id").GetGuid())).StatusCode);
        }
        var past = await CreateShowAsync(venueId, startsAt: DateTime.UtcNow.AddDays(-1));
        Assert.AreEqual(HttpStatusCode.Conflict, (await BookAsync(past.GetProperty("id").GetGuid())).StatusCode);
    }

    [TestMethod]
    public async Task RightsAreEnforced()
    {
        var venueId = (await CreateVenueAsync()).GetProperty("id").GetGuid();
        AuthenticateAs();
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/venues")).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/shows")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.GetAsync("/bookings")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.DeleteAsync($"/venues/{venueId}")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.PostAsJsonAsync("/shows", new { })).StatusCode);
        AuthenticateAs("ManageShows");
        Assert.AreEqual(HttpStatusCode.OK, (await Client.GetAsync("/bookings")).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, (await Client.DeleteAsync($"/venues/{venueId}")).StatusCode);
        AuthenticateAs("ManageVenues");
        Assert.AreEqual(HttpStatusCode.NoContent, (await Client.DeleteAsync($"/venues/{venueId}")).StatusCode);
        Unauthenticate();
        Assert.AreEqual(HttpStatusCode.Unauthorized, (await Client.PostAsJsonAsync("/box-office/book", new { })).StatusCode);
    }
}

[TestClass]
public class JwtTests : ApiTestBase
{
    private const string Key = "secret";

    protected override bool UseTestAuthentication => false;

    protected override void ConfigureWebHost(Microsoft.AspNetCore.Hosting.IWebHostBuilder builder) =>
        builder.UseSetting("Jwt:Key", Key);

    private static string Token(string key, DateTime expires, params string[] rights)
    {
        var bytes = new byte[32];
        Array.Fill(bytes, (byte)' ');
        Encoding.UTF8.GetBytes(key).CopyTo(bytes, 0);
        var creds = new SigningCredentials(new SymmetricSecurityKey(bytes), SecurityAlgorithms.HmacSha256);
        var token = new JwtSecurityToken(claims: rights.Select(r => new Claim("right", r)),
            notBefore: expires.AddHours(-2), expires: expires, signingCredentials: creds);
        return new JwtSecurityTokenHandler().WriteToken(token);
    }

    private HttpResponseMessage Send(string? token, string uri = "/venues")
    {
        var request = new HttpRequestMessage(HttpMethod.Get, uri);
        if (token is not null) request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token);
        return Client.SendAsync(request).Result;
    }

    [TestMethod]
    public void TokensAreValidated()
    {
        Assert.AreEqual(HttpStatusCode.Unauthorized, Send(null).StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, Send("garbage").StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, Send(Token("other", DateTime.UtcNow.AddHours(1))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Unauthorized, Send(Token(Key, DateTime.UtcNow.AddMinutes(-1))).StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, Send(Token(Key, DateTime.UtcNow.AddHours(1))).StatusCode);
        Assert.AreEqual(HttpStatusCode.Forbidden, Send(Token(Key, DateTime.UtcNow.AddHours(1)), "/bookings").StatusCode);
        Assert.AreEqual(HttpStatusCode.OK, Send(Token(Key, DateTime.UtcNow.AddHours(1), "*"), "/bookings").StatusCode);
    }
}
